2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.OwnerEmailInvalidException;
9	import org.springframework.samples.petclinic.rest.escalation.OwnerFieldsRequiredException;
10	import org.springframework.samples.petclinic.rest.escalation.OwnerTelephoneInvalidException;
11	import org.springframework.web.bind.annotation.RequestBody;
12	
13	/**
14	 * First step of {@code POST /api/owners}. Rejects a request that is missing or blank in any of
15	 * firstName, lastName, address, city or telephone, collecting every offending field name so the
16	 * response can list them all. It then normalizes the telephone into E.164 form (see
17	 * {@link OwnerTelephone#toE164(String)}), storing that value back on the body so it is persisted and
18	 * returned. On success it publishes the body for {@link BuildOwner} to consume
19	 * (only one step may bind {@code @RequestBody}).
20	 */
21	public class ValidateOwnerFields {
22	
23	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
24	            throws OwnerFieldsRequiredException, OwnerTelephoneInvalidException, OwnerEmailInvalidException {
25	        List<String> errors = new ArrayList<>();
26	        require("firstName", request.getFirstName(), errors);
27	        require("lastName", request.getLastName(), errors);
28	        require("address", request.getAddress(), errors);
29	        require("city", request.getCity(), errors);
30	        require("telephone", request.getTelephone(), errors);
31	        if (!errors.isEmpty()) {
32	            throw new OwnerFieldsRequiredException(errors);
33	        }
34	        request.setTelephone(OwnerTelephone.toE164(request.getTelephone()));
35	        request.setEmail(OwnerEmail.normalize(request.getEmail()));
36	        validated.set(request);
